import { test } from "node:test";
import assert from "node:assert/strict";
import { calcTotal, shippingFee } from "../src/pricing.ts";

test("shippingFee is free when the cart total is $50 or more", () => {
  assert.equal(shippingFee([{ sku: "a", price: 25, qty: 2 }]), 0);
  assert.equal(shippingFee([{ sku: "a", price: 10, qty: 5 }]), 0);
  assert.equal(shippingFee([{ sku: "a", price: 20, qty: 2 }, { sku: "b", price: 5, qty: 2 }]), 0);
});

test("shippingFee is unchanged below $50", () => {
  assert.equal(shippingFee([{ sku: "a", price: 49, qty: 1 }]), 5);
  assert.equal(shippingFee([{ sku: "a", price: 3, qty: 1 }]), 5);
  assert.equal(shippingFee([{ sku: "a", price: 40, qty: 1 }, { sku: "b", price: 9, qty: 1 }]), 5);
  assert.equal(shippingFee([]), 0);
});

test("the $50 threshold is measured on calcTotal", () => {
  const items = [{ sku: "a", price: 25, qty: 2 }];
  assert.equal(calcTotal(items), 50);
  assert.equal(shippingFee(items), 0);
});

